DROP VIEW IF EXISTS `top3_citi_count_v`;
CREATE VIEW `top3_citi_count_v` AS SELECT `全国授课动态`.`citi` AS `citi`, count(0) AS `count_num`, row_number() OVER (ORDER BY count(0) desc, `全国授课动态`.`citi`) AS `rank_num` FROM `全国授课动态` GROUP BY `全国授课动态`.`citi` ORDER BY `rank_num`;

DROP VIEW IF EXISTS `top3_industry_count_v`;
CREATE VIEW `top3_industry_count_v` AS SELECT `全国授课动态`.`industry` AS `industry`, count(0) AS `count_num`, row_number() OVER (ORDER BY count(0) desc, `全国授课动态`.`industry`) AS `rank_num` FROM `全国授课动态` GROUP BY `全国授课动态`.`industry` ORDER BY `rank_num`;

DROP VIEW IF EXISTS `v_industry_rank`;
CREATE VIEW `v_industry_rank` AS SELECT `全国授课动态`.`industry` AS `industry`, count(0) AS `count_num`, row_number() OVER (ORDER BY count(0) desc) AS `rank_num` FROM `全国授课动态` GROUP BY `全国授课动态`.`industry` ORDER BY `rank_num`;

DROP VIEW IF EXISTS `v_table_stats`;
CREATE VIEW `v_table_stats` AS SELECT count(0) AS `total_rows`, count(DISTINCT `全国授课动态`.`citi`) AS `distinct_citi_count`, count(DISTINCT `全国授课动态`.`industry`) AS `distinct_industry_count` FROM `全国授课动态`;

